contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: attempt to call refund and check observable Ether movement
    function run(uint256 dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);
        // observe Ether balances before calling refund
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeThisBalance = address(this).balance;

        bool refundReverted;
        c.refund(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            refundReverted = true;
        } else {
            refundReverted = false;
        }

        // observe balances after refund attempt
        uint256 afterContractBalance = address(c).balance;
        uint256 afterThisBalance = address(this).balance;

        // General rule: if refund did not revert then the decrease in c's balance equals the increase in this contract's balance
        assert(refundReverted || (beforeContractBalance - afterContractBalance == afterThisBalance - beforeThisBalance));
    }

    receive() external payable {}
}

