// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 dummy) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(true);
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeThisBalance = address(this).balance;
        bool refundReverted;
        try c.refund() {
            refundReverted = false;
        } catch {
            refundReverted = true;
        }
        uint256 afterContractBalance = address(c).balance;
        uint256 afterThisBalance = address(this).balance;
        assertTrue(refundReverted || (beforeContractBalance - afterContractBalance == afterThisBalance - beforeThisBalance));
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
